    snapshot_id: int
    asof_date: str
    scenario_id: int
    ids: Annotated[list[int], Field(max_length=6, min_length=2)]
    rows: list[ScoreRow]
    components: Annotated[ComponentMatrix, Field(title="ComponentMatrix")]
    ladders: dict[str, list[LadderRow]]
    gaps: dict[str, Gap]
