class Decision(BaseModel):
    """
    상황별 decide의 후보 1개 (RA §3 decision, §6-4, §6-7). 한 decide 호출(=DecisionSet)에 후보 ≤6 + escape hatch(ask_user, investigate) 행이 있다.
    - option_key: complex(단지 후보) | wait_new(모집공고 대기) | ask_user | investigate | none.
    - requirements: 요건 3개 각각 사전 계산(pre: 충족/미충족/미입력/확인 불가 + 근거 숫자 문자열)과 판정기 판정(judge: supported/contradicted/unknown). 둘이 다르면(충족↔contradicted, 미충족↔supported) 그 요건 mismatch=true이고 행 mismatch=true → '증거와 상이' 배지. 미입력·확인 불가·unknown은 불일치로 치지 않는다. 숨기지 않고 둘 다 보여준다.
    - tie: decide confidence < 0.6이면 확률 상위 2개 후보 모두 tie=true·chosen=true(1순위를 하나로 말하지 않음, T2).
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    id: int | None = None
    score_run_id: int | None = None
    scenario_id: int | None = None
    option_key: Literal["complex", "wait_new", "ask_user", "investigate", "none"]
    complex_id: int | None
    label: str
    """
    표시 이름(단지명 또는 '모집공고 대기' 등)
    """
    prob: Fact
    chosen: bool
    tie: bool
    mismatch: bool
    confidence: Annotated[float | None, Field(ge=0.0, le=1.0)] = None
    requirements: RequirementChecks | None
    judgment_seq: int | None = None


class DecisionBadge(BaseModel):
    """
    ScoreRow에 붙는 decide 요약. tie=true면 TieBadge, mismatch=true면 MismatchBadge('증거와 상이').
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    prob: Fact
    chosen: bool
    tie: bool
    mismatch: bool
    confidence: Annotated[float | None, Field(ge=0.0, le=1.0)] = None


class DecisionSet(BaseModel):
    """
    한 시나리오의 decide 호출 1회 결과 = C7 데이터(CompareView.decisions[scenario code]). status=escaped면 막대 대신 question 텍스트(G5 상단 배너 '판정기가 질문을 남겼습니다'). warnings는 그대로 보고.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    scenario_id: int
    scenario_code: str | None
    score_run_id: int | None = None
    judgment_seq: int | None = None
    status: Literal["ok", "review", "escaped", "blocked", "error"]
    confidence: Fact | None
    tie: bool
    escaped: bool
    question: str | None
    warnings: list[str]
    cached: bool
    items: list[Decision]


class Error(BaseModel):
    """
    모든 4xx·5xx 응답 본문 (RA §4-1).
    code 의미와 HTTP 상태:
    - unauthorized (401): 토큰 없음·불일치
    - forbidden (403): 읽기 전용 토큰으로 GET 이외 호출
    - not_found (404): 리소스 없음
    - validation_error (422): 요청 검증 실패 (field_errors 채움). 생활권 편집에서 법정동 누락·중복도 여기
    - conflict (409): 상태 충돌 (예: 완료되지 않은 보고서 다운로드)
    - publish_blocked (409): contradicted claim이 남아 publish·보고서 생성 불가 (detail에 개수)
    - intake_unknown (422): 접수 상태가 확인 불가라 요청한 동작(후보 포함 등)을 할 수 없음
    - judge_unavailable (503): 판정기 다운(degraded). 조회는 계속 가능
    - contract_violation (500): 출처(provenance) 없는 수치를 내보내려 함 (ENV=dev)
    - internal (500): 그 밖의 서버 오류
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    code: Literal[
        "unauthorized",
        "forbidden",
        "not_found",
        "validation_error",
        "conflict",
        "publish_blocked",
        "intake_unknown",
        "judge_unavailable",
        "contract_violation",
        "internal",
    ]
    detail: str
    field_errors: list[FieldError] | None = None
    request_id: str | None = None


class ExpectedComplex(BaseModel):
    model_config = ConfigDict(
        extra="forbid",
    )
    key: Annotated[str, Field(pattern="^[a-z0-9_]+$")]
    complex_id: int | None = None
    """
    OpenAPI 예시·픽스처에서 쓰는 id(1~16)
    """
    name: str
    area: str
    """
    보고서 구분(인천 송도/검단/계양, 김포)
    """
    judge_scope: Annotated[
        Literal["판정 대상", "보류", "참고", "미해결", "제외"],
        Field(title="JudgeScope"),
    ]
    """
    판정 범위(meta §1-3-4, DECISIONS D9-1 — 공용 함수 analysis/scope.py judge_scope() 하나로만 계산; API·파이프라인·보고서가 같은 함수를 부른다).
    - 제외: 포함/제외 classify(auto)가 제외 클래스(공공·임대·비아파트·범위 밖) 또는 '범위 경계'.
    - 보류: 포함 확정이나 분양가 미공개(공고 전) — 표시 '보류 — 공고 후 재판정'. 사다리·가격 갭 없음, rerank만.
    - 미해결: 포함/제외 classify 가 review·escaped·미분류 — 표시 '미해결(분류 판정 미해결)'. 판정 대상 아님, 사다리·점수 없음(계약 2026-10-09.4).
    - 참고: 포함 확정 + 가격 있음 + 접수 상태 '확인 불가' 또는 '불가' — 표시 '참고 후보(순위만)'. 사다리 미실행, rerank 후보에는 포함.
    - 판정 대상: 포함 확정 + 가격 있음 + 접수 '가능' 또는 '미정'.
    """
    intake_note: str | None = None
    components: Annotated[ExpectedComponents, Field(title="ExpectedComponents")]
    raw: Annotated[ExpectedRaw, Field(title="ExpectedRaw")]
    report_total: float | None
    report_rank: int | None
    computed_total: float | None
    expected_rank: int | None
    tie_group: int | None
    component_notes: dict[str, str] | None = None


