class ExpectedScores(BaseModel):
    """
    회귀 골든 파일 contracts/fixtures/<fixture>/expected_scores.json 의 스키마 (RA §9 (a)단계). 보고서의 구성 점수 6개를 입력으로 고정하고 가중 합·순위·동점만 검증한다(손 등급 시절의 숫자 그대로). (b)단계(§6-4 식으로 다시 계산한 값)는 expected_scores_v2.json으로 따로 고정한다(R1 끝, 사람 확인).
    - complexes[].components: 보고서 구성 점수(0~10, 입력). null이면 그 단지는 종합 미계산(보류·참고).
    - complexes[].report_total / report_rank: 보고서에 적힌 값(기대값의 원천). computed_total: 가중 합 원값(반올림 전) — |computed_total − report_total| ≤ tolerance.
    - complexes[].expected_rank / tie_group: RA §6-4 동점 규칙(|ΔS| < epsilon, 반올림 전 원값 비교, 리더 기준 그룹, 경쟁 순위)을 적용한 순위 — ScoreEngine이 내야 하는 값. 보고서 순위와 다르면 discrepancies에 적는다.
    - t1·t2: RA §9 수용 테스트 기대값. t7: 인천 8후보 → 16후보 rerank 변화. t12: §6-6 민감도를 같은 입력으로 계산한 값(사람 확인 전).
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    fixture: str
    contract_version: str
    stage: Literal["a"]
    source: Annotated[ExpectedSource, Field(title="ExpectedSource")]
    weights: Weights
    tie_rule: Annotated[TieRule, Field(title="TieRule")]
    tolerance: float
    complexes: list[ExpectedComplex]
    t1: Annotated[ExpectedT1, Field(title="ExpectedT1")]
    t2: Annotated[ExpectedT2, Field(title="ExpectedT2")]
    decide_integrated: dict[str, ExpectedDecide] | None = None
    """
    보고서 §12-5-2 상황별 decide 5회(#125~129) 결과. checks는 요건 순서를 access/regulation/funds로 옮긴 것.
    """
    t7_incheon_only: Annotated[ExpectedT7 | None, Field(title="ExpectedT7")] = None
    t12_sensitivity: Annotated[ExpectedT12 | None, Field(title="ExpectedT12")] = None
    discrepancies: list[ExpectedDiscrepancy] | None = None


