class LadderRow(BaseModel):
    """
    상승 확률 사다리 1개 시점 (RA §3 ladder, §6-3) — noul 1회 결과. (snapshot_id, complex_id, horizon) 유일, horizon 3종.
    - move_in_plus_1y: 입주월 + 12개월(즉시 입주면 기준일 + 12개월), 단지 자체 판단·s_p10 입력
    - asof_plus_3y: 기준일 + 36개월, 입주 시기가 다른 단지 비교(목표 시점이 모든 단지에서 같다, T10)
    - asof_plus_5y: 기준일 + 60개월, 상황 C
    명제 템플릿(meta §2-2): "{단지} 전용 {타입}을 {기준일} 현재 구매가({범위}, 구성)로 매수할 경우, {시점 설명}인 {target_label} 실거래가가 현재 구매가 대비 +5% / +10% / +20% 이상이다 / 이하(보합·하락)이다".
    annualized: 임계 상승률 g(0.05, 0.10, 0.20)를 연율로 환산 r = (1+g)^(12/m) − 1, m = months_from_asof.
    status가 review·escaped면 C1은 회색 막대 + '미해결', 확률은 점수에 쓰지 않는다.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    complex_id: int
    snapshot_id: int | None = None
    horizon: Literal["move_in_plus_1y", "asof_plus_3y", "asof_plus_5y"]
    target_ym: Annotated[str, Field(pattern="^[0-9]{4}-[0-9]{2}$")]
    target_label: str | None = None
    """
    부제용 '2029 상반기' 형식
    """
    months_from_asof: Annotated[int, Field(ge=1)]
    p5: Fact
    p10: Fact
    p20: Fact
    p_flat: Fact
    verdicts: Annotated[LadderVerdicts, Field(title="LadderVerdicts")]
    annualized: Annotated[LadderAnnualized, Field(title="LadderAnnualized")]
    status: Literal["ok", "review", "escaped", "blocked", "error"]
    judgment_seq: int | None
    proposition_text: str | None = None


