class RawDocument(BaseModel):
    """
    원문 1건 (RA §3 raw_document) — Collector.fetch의 반환 원소, Parser.parse의 입력. 원문 파일은 RAW_DIR/{source_kind}/{yyyy-mm-dd}/{sha256}.{ext}.
    - 멱등: sha256 유일 — 같은 내용이면 저장하지 않고 기존 행을 돌려준다.
    - 실패도 데이터: 403·5xx는 http_status에, DNS 실패·타임아웃은 http_status=null + error_text. 실패 행의 sha256 = sha256('fail:' + url + ':' + (http_status 또는 error 종류) + ':' + fetched_at의 날짜) — 같은 날 재시도는 중복 저장되지 않고 날마다 한 행이 남는다. 실패 행은 path=null.
    - official_site의 팝업 스크린샷은 image_hash(지각 해시 또는 sha256)를 남겨 변경 감지(WP7)에 쓴다.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    id: int | None = None
    source_kind: Annotated[
        Literal[
            "applyhome_list",
            "applyhome_detail",
            "notice_pdf",
            "official_site",
            "rtms",
            "stats",
            "news",
            "reference",
        ],
        Field(title="SourceKind"),
    ]
    """
    원문 출처 종류 (RA §3 + DECISIONS D2-1 reference)
    """
    url: Annotated[str, Field(min_length=1)]
    fetched_at: str
    http_status: int | None
    sha256: Annotated[str, Field(pattern="^[0-9a-f]{64}$")]
    path: str | None
    """
    RAW_DIR 기준 상대 경로. 실패 행은 null
    """
    content_type: str | None
    text_path: str | None
    """
    추출 텍스트(pdfplumber txt, DOM 텍스트) 상대 경로
    """
    table_path: str | None = None
    """
    추출 표 JSON 상대 경로(공고문 PDF: pdfplumber extract_tables → [{page, tables: [[[셀…]…]…]}], 표가 있는 페이지만). 표가 없거나 실패 행이면 null — 2026-10-09.2
    """
    complex_id: int | None
    region_id: int | None = None
    error_text: str | None = None
    """
    실패·부분 실패 사유 한 단어(+세부). 값 목록(2026-10-09.2):
    - 응답 없음: 'DNS' · 'timeout' · 'connect' · 'TLS' · 'network' · 'robots'(robots.txt 규칙상 불허) · 'robots.txt <코드>'(robots.txt 5xx로 전부 불허) · 'invalid_url' · 'render'(헤드리스 렌더 실패)
    - 성공 응답이지만 내용 문제(공고문 PDF): 'scan'(텍스트 레이어 없음 → 확인 불가(스캔)) · 'ocr'(전 페이지 OCR → 값 라벨 '추정(OCR)') · 'scan_partial:<p,…>' · 'ocr_partial:<p,…>'(1부터 센 페이지) · 'pdf_parse: <사유>'(파서 모두 실패) · 'not_pdf'(200이지만 PDF 아님)
    - 그 밖의 파싱 실패는 '<단계>: <사유>' 형식. 4xx·5xx 응답은 error_text 대신 http_status
    """
    image_hash: Annotated[str | None, Field(max_length=64)] = None
    meta: dict[str, Any] | None = None
    """
    수집기 부가 정보 JSON(원문 파일과 별도) — 예 official_site: {final_url, render: {reason, rendered, error, screenshot_sha256, signature, popups[{selector, sha256, width, height, images, text_sha256, dhash, signature}]}, intake_candidates[]} — render.signature·popups[].signature 는 시각·애니메이션을 무시한 안정 해시(DOM 텍스트 정규화 sha256 + perceptual dhash, 변경 감지는 이것으로 — R3 M13, 계약 2026-10-09.4 문서화), notice_pdf: {pages, ocr_pages[]}. 키는 source_kind별로 수집기가 정하고 README에 적는다. 판단 값을 넣지 않는다 — 2026-10-09.2
    """


class ReferenceRefreshPayload(BaseModel):
    """
    job_name='reference.refresh' 페이로드 (DECISIONS D2-4). 최초 기동 시 1회 + 매월 1일 05:00. 법정동·행정동·매핑·세대 현황 파일을 받아 legal_dong·admin_dong·admin_legal_map·household_stat에 적재한다. 다운로드가 실패하면 contracts/fixtures/reference/ 사본으로 동작한다. 페이로드는 빈 객체.
    """

    model_config = ConfigDict(
        extra="forbid",
    )


class Region(BaseModel):
    """
    사용자가 입력한 지역 1개 (RA §3 region + DECISIONS D2-2). 프로그램은 특정 지역 전용이 아니다 — 지역은 사용자가 고른 후보(selections)의 묶음이고 코드에 지역명을 하드코딩하지 않는다.
    - sido_codes: 청약홈 목록 조회용(2자리). 결과 단지 주소를 legal_dong 이름으로 매칭해 legal_dong_codes에 속한 것만 남긴다(D2-6). 매칭 실패 단지는 complex.inclusion_class='범위 경계'.
    - sigungu_codes: 실거래 Open API 조회용(5자리).
    - legal_dong_codes: 이 지역의 법정동 전체(10자리).
    - living_areas: 생활권 정의. 모든 법정동은 정확히 한 생활권에 속한다.
    - age_premium_coef: 가격 갭 연식 보정 계수 c와 상한(기본 0.015/년, 8년, 라벨 추정 — DECISIONS D1-2).
    - supply_ref_pct: 공급 기준치 U_ref = 생활권 세대수 × 이 비율(기본 0.08, 라벨 추정 — D1-3).
    - status: resolving(후보 확정 중) → bootstrapping(region.bootstrap 잡 실행 중) → ready / failed.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    id: int
    name: Annotated[str, Field(max_length=100, min_length=1)]
    query_text: str
    """
    사용자가 입력한 원문
    """
    selections: Annotated[list[RegionSelection], Field(min_length=1)]
    sido_codes: list[str]
    """
    시도 코드 2자리 문자열
    """
    sigungu_codes: list[str]
    """
    시군구 코드 5자리 문자열
    """
    legal_dong_codes: list[str]
    """
    법정동 코드 10자리 문자열
    """
    living_areas: list[LivingArea]
    age_premium_coef: AgePremiumCoef
    supply_ref_pct: Annotated[float, Field(gt=0.0, le=1.0)]
    applyhome_query: dict[str, Any]
    """
    청약홈 조회 파라미터 — 키 정의는 $defs/ApplyhomeQuery(from_ym, areas). 저장·전달은 자유 json 객체(수집기는 ApplyhomeQuery.model_validate 로 읽을 수 있다)
    """
    status: Literal["resolving", "bootstrapping", "ready", "failed"]
    created_at: str
    latest_snapshot: Snapshot | None = None
    """
    GET /regions 에서 최신 스냅샷(없으면 null)
    """


class RegionBootstrapPayload(BaseModel):
    """
    job_name='region.bootstrap' 페이로드 (DECISIONS D2-4). POST /regions가 넣는다. collect.daily + collect.weekly 즉시 실행 → 스냅샷 생성 → 판정 파이프라인 P1~P9 → 점수 → publish. 진행 중 region.status='bootstrapping', 끝나면 ready/failed.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    region_id: int


class RegionCandidate(BaseModel):
    """
    GET /regions/resolve?q= 의 후보 1건 (DECISIONS D2-3). 자유 지명을 legal_dong·admin_dong 참조 테이블과 문자열 매칭한 결과다(판정기 호출 없음 — 문자열 매칭은 판단이 아님).
    매칭 규칙: 공백과 접미사 '시/군/구/동/읍/면'을 무시하고 이름 부분 일치. 정렬은 match(exact > prefix > partial) → kind(sido > sigungu > admin_dong > legal_dong) → full_name.
    legal_dong_codes는 이 후보를 고르면 region에 들어갈 법정동(10자리) 전체다. sido·sigungu 후보는 하위 법정동 전부, admin_dong 후보는 admin_legal_map으로 펼친 법정동이다. 폐지 코드(active=false)는 포함하지 않는다.
    분구·개편으로 옛 코드와 새 코드가 함께 active면 둘 다 후보로 나온다(DECISIONS D3). 공식 표에서 옛 코드가 폐지되면(예 2026-07 분구 후 서구 28260 폐지·검단구 28290 신설) 새 코드만 나온다.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    kind: Literal["sido", "sigungu", "admin_dong", "legal_dong"]
    code: Annotated[str, Field(pattern="^[0-9]{2}([0-9]{3}([0-9]{5})?)?$")]
    """
    sido 2자리, sigungu 5자리, admin_dong·legal_dong 10자리
    """
    full_name: str
    legal_dong_codes: list[str]
    """
    법정동 코드 10자리 문자열
    """
    match: Literal["exact", "prefix", "partial"]
    sigungu_code: Annotated[str | None, Field(pattern="^[0-9]{5}$")] = None
    sido_code: Annotated[str | None, Field(pattern="^[0-9]{2}$")] = None


