class Weights(BaseModel):
    """
    가중치 6개(각 0~1, 합 = 1). 저장되는 시나리오 가중치는 10진 합이 정확히 1(검증 허용 오차 1e-9), 민감도 변형 가중치는 표시 반올림 때문에 1e-6까지 허용. liquidity와 move_in 중 정확히 하나만 있다.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    p10: Annotated[float, Field(ge=0.0, le=1.0)]
    rerank: Annotated[float, Field(ge=0.0, le=1.0)]
    gap: Annotated[float, Field(ge=0.0, le=1.0)]
    benchmark: Annotated[float, Field(ge=0.0, le=1.0)]
    supply: Annotated[float, Field(ge=0.0, le=1.0)]
    liquidity: Annotated[float | None, Field(ge=0.0, le=1.0)] = None
    move_in: Annotated[float | None, Field(ge=0.0, le=1.0)] = None
